/**
 * Disposable-email blocking for sign-up, and email normalisation so one inbox
 * cannot sign up many times as `me+1@`, `me+2@`, `m.e@gmail.com`.
 *
 * ```ts
 * app.use("/api/auth/sign-up/*", blockDisposableEmail({ allow: ["our-partner.example"] }))
 * if (isDisposableEmail(email)) throw new ApiException(400, "...", "DISPOSABLE_EMAIL")
 * const key = normalizeEmail(email) // store and compare this, not the raw address
 * ```
 *
 * The bundled list (`DISPOSABLE_DOMAINS`, ~10k domains) is generated by
 * `scripts/disposable-domains.ts` from a CC0 community list. A subdomain of a
 * listed domain is disposable too (`x.mailinator.com`).
 */

import type { Context, MiddlewareHandler } from "hono"
import { DISPOSABLE_DOMAINS } from "./disposable-domains.js"

let bundled: Set<string> | undefined
const list = () => {
  bundled ??= new Set(DISPOSABLE_DOMAINS.split("\n"))
  return bundled
}

/** Providers that ignore dots in the local part, and their alias domains. */
const DOTLESS: Record<string, string> = { "gmail.com": "gmail.com", "googlemail.com": "gmail.com" }

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

/** The domain of an address, lowercase and without a trailing dot, or null if it is not an address. */
export function emailDomain(email: string | null | undefined): string | null {
  const e = email?.trim().toLowerCase()
  if (!e || !EMAIL.test(e)) return null
  return e.slice(e.lastIndexOf("@") + 1).replace(/\.$/, "")
}

/**
 * One key per inbox: lowercase, the `+tag` dropped, and for Gmail the dots
 * dropped and googlemail.com read as gmail.com. Null if not an address. Use
 * it to find duplicates; send mail to the address the person typed.
 */
export function normalizeEmail(email: string | null | undefined): string | null {
  const domain = emailDomain(email)
  if (!domain) return null
  const e = (email as string).trim().toLowerCase()
  let local = e.slice(0, e.lastIndexOf("@"))
  const plus = local.indexOf("+")
  if (plus > 0) local = local.slice(0, plus)
  const dotless = DOTLESS[domain]
  if (dotless) local = local.replaceAll(".", "")
  return `${local}@${dotless ?? domain}`
}

export type DisposableEmailOptions = {
  /** More domains to block (subdomains included). */
  add?: readonly string[]
  /** Domains never blocked, even when listed (subdomains included). Wins over `add`. */
  allow?: readonly string[]
}

/** The domain and each parent: `a.b.example.com`, `b.example.com`, `example.com`. */
function* parents(domain: string) {
  let d = domain
  while (d.includes(".")) {
    yield d
    d = d.slice(d.indexOf(".") + 1)
  }
}

const toSet = (xs?: readonly string[]) =>
  new Set((xs ?? []).map((d) => d.trim().toLowerCase().replace(/^@/, "")).filter(Boolean))

/**
 * A checker with the app's own additions and exceptions, built once:
 * `(email) => true` for a disposable address. A string that is not an
 * address is not disposable; validate it separately.
 */
export function disposableEmailChecker(opts: DisposableEmailOptions = {}) {
  const add = toSet(opts.add)
  const allow = toSet(opts.allow)
  return (email: string | null | undefined): boolean => {
    const domain = emailDomain(email)
    if (!domain) return false
    for (const d of parents(domain)) if (allow.has(d)) return false
    for (const d of parents(domain)) if (add.has(d) || list().has(d)) return true
    return false
  }
}

/** True for an address at a disposable domain. See `disposableEmailChecker` to reuse options. */
export const isDisposableEmail = (
  email: string | null | undefined,
  opts?: DisposableEmailOptions,
) => disposableEmailChecker(opts)(email)

export type BlockDisposableEmailOptions = DisposableEmailOptions & {
  /** The JSON or form body field holding the address. Default "email". */
  field?: string
  /** The message shown. Default "Use a permanent email address." */
  message?: string
}

/**
 * Refuses a request whose body's email is disposable: 400 `DISPOSABLE_EMAIL`
 * with the field in `details.fieldErrors`. Reads a clone of the body, so the
 * route (or Better Auth's handler) still gets it. A missing or malformed
 * address passes through for the route's own validation.
 */
export function blockDisposableEmail(opts: BlockDisposableEmailOptions = {}): MiddlewareHandler {
  const field = opts.field ?? "email"
  const message = opts.message ?? "Use a permanent email address."
  const disposable = disposableEmailChecker(opts)
  return async (c: Context, next) => {
    const email = await bodyField(c, field)
    if (!disposable(email)) return next()
    const requestId = c.get("reqId" as never) as string | undefined
    return c.json(
      {
        success: false as const,
        error: message,
        code: "DISPOSABLE_EMAIL",
        details: { formErrors: [], fieldErrors: { [field]: [message] } },
        ...(requestId ? { requestId } : {}),
      },
      400,
    )
  }
}

async function bodyField(c: Context, field: string): Promise<string | undefined> {
  const type = c.req.header("content-type") ?? ""
  try {
    if (type.includes("application/json")) {
      const b = (await c.req.raw.clone().json()) as Record<string, unknown> | null
      return typeof b?.[field] === "string" ? (b[field] as string) : undefined
    }
    if (type.includes("form")) {
      const v = (await c.req.raw.clone().formData()).get(field)
      return typeof v === "string" ? v : undefined
    }
  } catch {}
  return undefined
}
